def is_decimal(s):
    if not isinstance(s, str):
        return False
    if '.' not in s:
        return False
    parts = s.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    # Allow negative sign only in the integer part, at the start
    if integer_part.startswith('-'):
        integer_part = integer_part[1:]
    # Integer part and decimal part must be digits only
    if not integer_part.isdigit():
        return False
    if len(decimal_part) != 2 or not decimal_part.isdigit():
        return False
    return True

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False
    # The string must contain exactly two distinct characters
    chars = set(s)
    if len(chars) != 2:
        return False
    # Check if characters alternate properly
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            return False
    return True

